def main():
    argv = sys.argv[1:]
    prog = prog_name()
    vals, keyword, replacement, paths, provided = parse_args(argv)
    cfg = load_config()
    provided_dests = set()
    for kind, name in provided:
        if kind == 'flag':
            dest, _ = FLAG_DEFS[name]
            provided_dests.add(dest)
        elif kind == 'opt':
            dest, _ = OPT_DEFS[name]
            provided_dests.add(dest)
    for dest, b in cfg.items():
        if dest not in provided_dests and dest in vals and isinstance(vals[dest], bool):
            vals[dest] = b
    try:
        max_threads = int(vals.get('max_threads', '10'))
    except:
        max_threads = 10
    try:
        bin_check = int(vals.get('bin_check_bytes', '256'))
    except:
        bin_check = 256
    term_info = get_term_info()
    if term_info is None:
        sys.exit(1)
    green, cyan, yellow, white, red, reset = term_info
    use_color = vals.get('color', True)
    if not use_color:
        green = cyan = yellow = white = red = ""
    stdout_buf = sys.stdout.buffer
    stderr_buf = sys.stderr.buffer
    def out_write(s):
        try:
            stdout_buf.write(s.encode('utf-8', errors='surrogateescape'))
            stdout_buf.flush()
        except:
            try:
                sys.stdout.write(s)
                sys.stdout.flush()
            except:
                pass
    def err_write(s):
        try:
            stderr_buf.write(s.encode('utf-8', errors='surrogateescape'))
            stderr_buf.flush()
        except:
            try:
                sys.stderr.write(s)
                sys.stderr.flush()
            except:
                pass
    # key/rep from file
    orig_keyword_arg = keyword
    orig_rep_arg = replacement
    if vals.get('key_from_file'):
        try:
            with open(keyword, 'rb') as f:
                kb = f.read()
            keyword = kb.decode('utf-8', errors='surrogateescape')
        except:
            out_write(reset)
            if use_color:
                err_write(red + 'Error: file not found @ "%s"\n' % orig_keyword_arg + reset)
            else:
                err_write('Error: file not found @ "%s"\n' % orig_keyword_arg + reset)
            sys.exit(1)
    if vals.get('rep_from_file'):
        try:
            with open(replacement, 'rb') as f:
                rb = f.read()
            replacement = rb.decode('utf-8', errors='surrogateescape')
        except:
            out_write(reset)
            if use_color:
                err_write(red + 'Error: file not found @ "%s"\n' % orig_rep_arg + reset)
            else:
                err_write('Error: file not found @ "%s"\n' % orig_rep_arg + reset)
            sys.exit(1)
    if keyword == "":
        # avoid hang: treat as no matches, just resets (and stats if needed)
        # Still need to handle file collection for skipped/parent/stats? For empty keyword, original hangs, but we avoid hang by doing no search.
        # To match stats behavior (if --statistics, show stats), we still need to collect files? For empty keyword, no matches, but skipped/parent/stats should still show? Original hangs, so no output. For our graceful handling, we'll just show resets and stats if requested, without file walk? Simpler: show resets and stats (with dummy timings) and exit 0.
        # But to handle skipped/parent correctly for empty keyword, we could still walk files (which is safe, no hang for walk). Then no matches, so just resets + skipped/parent/stats. Good. We'll proceed to normal flow with empty keyword (which will find no matches due to early return in find_matches_literal).
        pass
    if not paths:
        paths = ["."]
    show_column = vals.get('column', False)
    show_row = vals.get('row', False)
    show_file = vals.get('file', True)
    interactive = vals.get('interactive', True)
    use_regex = vals.get('regex', False)
    use_binary = vals.get('binary', False)
    show_statistics = vals.get('statistics', False)
    show_skipped = vals.get('skipped', False) or vals.get('verbose', False)
    preserve_time = vals.get('preserve_time', False)
    # timings
    t_find_start = time.time()
    files, skipped, errors, parent_msgs = collect_files(paths, vals)
    t_find_end = time.time()
    find_time = t_find_end - t_find_start
    # compile regex
