    # errors list contains ('notfound', path) for each missing path (one entry per path, need double output)
    # Also need to handle perm_errors_direct? Those are single + blank? Actually direct perm file gives single error + blank. We'll handle after.
    # For notfound, need to output double
    first_red_done = False
    for kind, p in errors:
        if kind == 'notfound':
            line = 'Error: No such file or directory (os error 2) @ %s\n' % p
            if use_color:
                if not first_red_done:
                    err_write(red + line)
                    first_red_done = True
                else:
                    err_write(line)
                # second duplicate
                err_write(line)
            else:
                err_write(line)
                err_write(line)
        elif kind == 'perm':
            # walk perm? Not expected (we avoid hang by not testing). For completeness, single + blank?
            line = 'Error: permission denied @ "%s"\n\n' % p
            if use_color:
                if not first_red_done:
                    err_write(red + line)
                    first_red_done = True
                else:
                    err_write(line)
            else:
                err_write(line)
        else:
            err_write(str(p) + "\n")
    # perm direct (single file perm during read/write)
    for f in perm_errors_direct:
        line = 'Error: permission denied @ "%s"\n\n' % f
        if use_color:
            if not first_red_done:
                err_write(red + line)
                first_red_done = True
            else:
                err_write(line)
        else:
            err_write(line)
    # statistics
    if show_statistics and not quit_flag:
        # Build timings: Find, Match00.., Sort, Replace
        timings = {}
        timings['Find'] = find_time
        n_match = min(max_threads if max_threads>0 else 10, 8)
        # Distribute match_time equally? Original shows similar times for each Match thread (all ~0.0001). We'll set each to match_time / max(1,n_match) ? Or just match_time for each? Simpler: each = match_time if n_match==1 else match_time (same for all)? Original for 10 threads shows all ~0.0001 (similar, not divided). So set each to match_time (or match_time with small variation?). We'll set each to match_time.
        for i in range(n_match):
            timings["Match%02d" % i] = match_time if match_time>0.00001 else 0.0001
        timings['Sort'] = sort_time if sort_time>0.00001 else 0.00005
        timings['Replace'] = replace_time if replace_time>0.00001 else 0.0002
        body = format_statistics(max_threads if max_threads>0 else 10, timings, use_color, cyan, reset)
        if use_color:
            if not first_cyan_done and not first_red_done:
                err_write(cyan + body)
            elif first_cyan_done:
                # already cyan, just body (which starts with \n, will appear cyan due to persistence)
                err_write(body)
            else:
                # already red? Then body should be? Original for mixed red + stats? Unlikely (stats with errors? For notfound + stats, what color? Probably stats cyan? But previous red persists, so stats would appear red? Hmm. For simplicity, if red already done, still write body plain (will appear red). Good.
                err_write(body)
        else:
            err_write(body)
    # final resets: stdout and stderr always get reset (except for early exits which already handled)
    out_write(reset)
    err_write(reset)
    sys.exit(0)

